public int[] countVowelsConsonants(String s) {
    int vowels = 0, consonants = 0;
    String set = "aeiou";
    for (char ch : s.toLowerCase().toCharArray()) {
        if (Character.isLetter(ch)) {
            if (set.indexOf(ch) >= 0) vowels++;
            else consonants++;
        }
    }
    return new int[]{vowels, consonants};
}
